  1|// csuite-inbox-watch monitors a C-Suite agent's inbox directory for new
  2|// messages and notifies the agent's tmux session via send-keys.
  3|//
  4|// Usage:
  5|//
  6|//	csuite-inbox-watch -agent kyle [-socket drem] [-dir ~/.drem-csuite]
  7|//
  8|// The watcher uses fsnotify (inotify on Linux) to react to new files
  9|// in $DIR/$AGENT/inbox/. When a .md file is created, it reads the YAML
 10|// frontmatter (from, subject, priority) and injects a one-line notification
 11|// into the agent's tmux session (csuite-$AGENT on the specified socket).
 12|package main
 13|
 14|import (
 15|	"bufio"
 16|	"flag"
 17|	"fmt"
 18|	"log"
 19|	"os"
 20|	"os/exec"
 21|	"path/filepath"
 22|	"strings"
 23|
 24|	"github.com/fsnotify/fsnotify"
 25|)
 26|
 27|func main() {
 28|	agent := flag.String("agent", "", "Agent name (e.g., kyle, mike, alex, ross, seth)")
 29|	socket := flag.String("socket", "drem", "Tmux socket name")
 30|	dir := flag.String("dir", "", "C-Suite base directory (default: ~/.drem-csuite)")
 31|	flag.Parse()
 32|
 33|	if *agent == "" {
 34|		log.Fatal("required: -agent <name>")
 35|	}
 36|
 37|	if *dir == "" {
 38|		home, err := os.UserHomeDir()
 39|		if err != nil {
 40|			log.Fatalf("cannot determine home directory: %v", err)
 41|		}
 42|		*dir = filepath.Join(home, ".drem-csuite")
 43|	}
 44|
 45|	inboxDir := filepath.Join(*dir, *agent, "inbox")
 46|	if _, err := os.Stat(inboxDir); os.IsNotExist(err) {
 47|		log.Fatalf("inbox directory does not exist: %s", inboxDir)
 48|	}
 49|
 50|	session := "csuite-" + *agent
 51|
 52|	watcher, err := fsnotify.NewWatcher()
 53|	if err != nil {
 54|		log.Fatalf("cannot create watcher: %v", err)
 55|	}
 56|	defer watcher.Close()
 57|
 58|	if err := watcher.Add(inboxDir); err != nil {
 59|		log.Fatalf("cannot watch %s: %v", inboxDir, err)
 60|	}
 61|
 62|	log.Printf("watching %s for agent %s (session %s on socket %s)", inboxDir, *agent, session, *socket)
 63|
 64|	for {
 65|		select {
 66|		case event, ok := <-watcher.Events:
 67|			if !ok {
 68|				return
 69|			}
 70|			if event.Has(fsnotify.Create) && strings.HasSuffix(event.Name, ".md") {
 71|				from, subject, priority := readFrontmatter(event.Name)
 72|				if from != "" {
 73|					note := fmt.Sprintf("[inbox] %s from %s: %s", priority, from, subject)
 74|					notify(session, *socket, note)
 75|					log.Printf("notified: %s", note)
 76|				}
 77|			}
 78|		case err, ok := <-watcher.Errors:
 79|			if !ok {
 80|				return
 81|			}
 82|			log.Printf("watcher error: %v", err)
 83|		}
 84|	}
 85|}
 86|
 87|// readFrontmatter extracts from, subject, and priority from YAML frontmatter.
 88|func readFrontmatter(path string) (from, subject, priority string) {
 89|	f, err := os.Open(path)
 90|	if err != nil {
 91|		return "", "", ""
 92|	}
 93|	defer f.Close()
 94|
 95|	scanner := bufio.NewScanner(f)
 96|	inFrontmatter := false
 97|
 98|	for scanner.Scan() {
 99|		line := scanner.Text()
100|		if line == "---" {
101|			if inFrontmatter {
102|				break // end of frontmatter
103|			}
104|			inFrontmatter = true
105|			continue
106|		}
107|		if !inFrontmatter {
108|			continue
109|		}
110|		if k, v, ok := parseYAMLField(line); ok {
111|			switch k {
112|			case "from":
113|				from = v
114|			case "subject":
115|				subject = v
116|			case "priority":
117|				priority = v
118|			}
119|		}
120|	}
121|
122|	if priority == "" {
123|		priority = "normal"
124|	}
125|	return from, subject, priority
126|}
127|
128|// parseYAMLField extracts a key-value pair from a simple YAML line.
129|func parseYAMLField(line string) (key, value string, ok bool) {
130|	parts := strings.SplitN(line, ":", 2)
131|	if len(parts) != 2 {
132|		return "", "", false
133|	}
134|	key = strings.TrimSpace(parts[0])
135|	value = strings.TrimSpace(parts[1])
136|	// Strip surrounding quotes
137|	value = strings.Trim(value, "\"'")
138|	return key, value, true
139|}
140|
141|// notify sends a tmux send-keys command to the agent's session.
142|func notify(session, socket, note string) {
143|	cmd := exec.Command("tmux", "-L", socket, "send-keys", "-t", session, note, "Enter")
144|	if err := cmd.Run(); err != nil {
145|		log.Printf("tmux send-keys failed (session %s may not be running): %v", session, err)
146|	}
